import torch


def run(x, dim0, dim1):
    return torch.ops.aten.transpose.int(x, dim0, dim1)


def gen_inputs(ctx, device):
    shape = tuple(ctx["x__shape"])
    dtype = getattr(torch, ctx["x__dtype"])
    base = torch.randn(shape, dtype=dtype, device=device)
    # Reproduce the non-contiguous slice used by test_transpose_non_contiguous.
    if shape[0] > 1:
        x = base[::2]
    else:
        x = base
    return {"x": x}
